using MagicCSharp.Generators.Declarations.AssemblyLoading;
using Microsoft.CodeAnalysis;

namespace MagicCSharp.Generators;

/// <summary>
///     Writes <c>{RootNamespace}.AssemblyLoader</c> in a project with <c>MagicCSharpGenerateAssemblyLoader=true</c>: a
///     module initializer that loads every referenced project before <c>Main</c>, so a scan for use cases and handlers
///     sees them all. Replaces the checked-in loader that had to be regenerated by hand after adding a project.
/// </summary>
[Generator(LanguageNames.CSharp)]
public sealed class AssemblyLoaderGenerator : IIncrementalGenerator
{
    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        var settings = context.AnalyzerConfigOptionsProvider.Select((options, _) => AssemblyLoaderSettings.Read(options));
        var readResult = context.CompilationProvider.Combine(settings)
            .Select((compilationAndSettings, cancellationToken) =>
                AssemblyLoaderReader.Read(compilationAndSettings.Left, compilationAndSettings.Right, cancellationToken));
        context.RegisterSourceOutput(readResult, WriteLoader);
    }

    private static void WriteLoader(SourceProductionContext sourceProductionContext, AssemblyLoaderReadResult readResult)
    {
        foreach (var diagnosticInfo in readResult.Diagnostics)
        {
            sourceProductionContext.ReportDiagnostic(diagnosticInfo.ToDiagnostic());
        }

        if (readResult.Declaration == null)
        {
            return;
        }

        var generatedFile = AssemblyLoaderWriter.WriteFile(readResult.Declaration);
        sourceProductionContext.AddSource(generatedFile.HintName, generatedFile.Text);
    }
}
